From gleam_stdlib 0.70.0 src/gleam/string.gleam (verified in build/packages/gleam_stdlib):
fn to_utf_codepoints_loop(
  bit_array: BitArray,
  acc: List(UtfCodepoint),
) -> List(UtfCodepoint) {
  case bit_array {
    <<first:utf8_codepoint, rest:bytes>> ->
      to_utf_codepoints_loop(rest, [first, ..acc])
    _ -> list.reverse(acc)
  }
}
Empirically verified with erl against the built beams: gleam@string:to_utf_codepoints(<<0,255,97>>) -> [0] (NUL kept as codepoint 0); gleam@string:from_utf_codepoints([0,97]) -> <<0,97>>; erlang:decode_packet(httph_bin, <<"X-Test: a",0,"b\r\nMore: x\r\n\r\n>>, []) -> {ok,{http_header,0,<<"X-Test">>,<<"X-Test">>,<<97,0,98>>},...} (mist's parser accepts NUL in header values) and gleam@bit_array:to_string(<<97,0,98>>) -> {ok,<<97,0,98>>} (mist's parse_headers `let assert Ok(value) = bit_array.to_string(value)` succeeds).

